(window.FJDATA=window.FJDATA||{})["metrics"]={"as_of":"2026-11-25","note":["القياسات والتقديرات في قسمين منفصلين. القياس له بداية ونهاية ومصدر وحد. التقدير موسوم بأنه تقدير ولا يُعرض قياسًا.","Measurements and estimates are kept in two separate sections. A measurement has a start, an end, a source and a limit. An estimate is labelled as an estimate and is never shown as a measurement."],"measured":[{"id":"commits_total","value":7937,"state":"verified","unit":["التزامًا","commits"],"label":["التزامات في مستودع سديد","Commits in the SADEED repository"],"start":"2026-05","end":"2026-11-25","source":["سجل الإيداعات في مستودع سديد · عُدّ في ٢٥ نوفمبر ٢٠٢٦","git history of the SADEED repository · counted on 25 November 2026"],"limit":["العدد يقيس وتيرة النشاط لا حجم القيمة، ولا يفرّق بين ما كتبناه بأيدينا وما كتبته أدوات البرمجة تحت مراجعتنا. المجموع يتضمن التزامًا شكليًّا واحدًا مؤرخًا في 2025-01-01.","The count measures activity, not value, and does not separate what we typed from what coding tools wrote under our review. The total includes one placeholder commit dated 2025-01-01."]},{"id":"active_days","value":127,"state":"verified","unit":["يومًا نشطًا","active days"],"label":["أيام تحمل التزامًا واحدًا على الأقل","Days that carry at least one commit"],"start":"2026-05","end":"2026-11-25","source":["سجل الإيداعات في مستودع سديد · عُدّ في ٢٥ نوفمبر ٢٠٢٦","git history of the SADEED repository · counted on 25 November 2026"],"limit":["اليوم يُحسب مرة واحدة مهما كثرت التزاماته. ليس عدد ساعات عمل ولا عدد أيام تقويم.","A day counts once however many commits it holds. It is neither working hours nor calendar days."]},{"id":"commits_last_30_days","value":1530,"state":"verified","unit":["التزامًا","commits"],"label":["التزامات آخر ثلاثين يومًا","Commits in the last 30 days"],"start":"2026-10-26","end":"2026-11-25","source":["سجل الإيداعات في مستودع سديد · عُدّ في ٢٥ نوفمبر ٢٠٢٦","git history of the SADEED repository · counted on 25 November 2026"],"limit":["نافذة متحركة تنتهي عند العد في ٢٥ نوفمبر ٢٠٢٦، وتاريخ بدايتها محسوب بطرح ثلاثين يومًا. الرقم يتغير مع كل يوم.","A rolling window ending at the count on 25 November 2026; its start date is computed by subtracting 30 days. The figure changes every day."]},{"id":"pr_merges","value":345,"state":"verified","unit":["دمجًا","merges"],"label":["دمج طلبات سحب في السجل","Pull-request merges in the history"],"start":"2026-05","end":"2026-11-25","source":["سجل الإيداعات في مستودع سديد · عُدّ في ٢٥ نوفمبر ٢٠٢٦","git history of the SADEED repository · counted on 25 November 2026"],"limit":["عدد عمليات الدمج، وليس عدد الميزات ولا حجم كل تغيير.","A count of merges, not of features and not of the size of each change."]},{"id":"highest_pr_number","value":826,"state":"verified","unit":["أعلى رقم طلب","highest request number"],"label":["أعلى رقم طلب سحب ظهر في السجل","Highest pull-request number seen in the history"],"start":"2026-05","end":"2026-11-25","source":["سجل الإيداعات في مستودع سديد · عُدّ في ٢٥ نوفمبر ٢٠٢٦","git history of the SADEED repository · counted on 25 November 2026"],"limit":["عدّاد وليس عدد طلبات مدموجة: يشمل ما أُغلق بلا دمج، وترقيم GitHub يجمع الطلبات والمسائل في تسلسل واحد.","A counter, not a count of merged requests: it includes requests closed without merging, and GitHub numbers pull requests and issues in one sequence."]},{"id":"release_interval_pr455","value":1042.791,"state":"observed","unit":["ثانية","seconds"],"display":["١٧ دقيقة و٢٢٫٧٩١ ثانية","17 min 22.791 s"],"label":["من الدمج إلى التحقق على النطاقين، تحديث سديد #455","From merge to verification on both domains, SADEED update #455"],"start":"2026-11-22T23:32:36Z","end":"2026-11-22T23:49:58.791Z","source":["طلب الدمج ٤٥٥ على GitHub · طابعان زمنيان مسجَّلان","GitHub · PR #455 · two recorded timestamps"],"limit":["زمن إصدار لتحديث واحد. لم يُقَس زمن تطوير الميزة، ولا يصلح مقياسًا عامًّا للإنتاجية. فحص المتصفح العام اللاحق عند ٢٣:٥٠:١٨٫٤١١ بالتوقيت العالمي مرحلة أخرى.","A release interval for one update. Feature development time was not measured, and this is no general productivity figure. The later public browser check at 23:50:18.411 UTC is a separate stage."]},{"id":"kpi_acceptance_cases","value":4,"state":"verified","unit":["حالات ناجحة من ٤","cases passed of 4"],"label":["اختبار قبول دالة المؤشر","Acceptance test of the KPI function"],"start":"2026-11-25","end":"2026-11-25","source":["فحص القبول · سجل التنفيذ","Acceptance check · execution log"],"limit":["عيّنة اصطناعية. يثبت الدالة ولا يثبت لوحة في الإنتاج.","A synthetic sample. It proves the function, not a production dashboard."]},{"id":"package_files_verified","value":110,"state":"verified","unit":["ملفات","files"],"label":["ملفات حزمة الأساس المطابقة لبصماتها في البيان","Baseline package files matching their manifest hashes"],"start":"2026-11-25","end":"2026-11-25","source":["فحص ملفات الحزمة · سجل التنفيذ","Package file check · execution log"],"limit":["يثبت سلامة الحزمة لا صحة محتواها. استُخرج ١١٣ ملفًا، وأفاد فحص البيان بمطابقة ١١٠.","It proves the package is intact, not that its content is correct. 113 files were extracted, and the manifest check reported 110 verified."]},{"id":"connected_services","value":23,"state":"observed","unit":["خدمة موصولة","connected services"],"label":["خدمات مربوطة بحساب المساعد الخاص بالمالك","Services linked to the owner’s assistant account"],"start":"2026-11-25","end":"2026-11-25","source":["قائمة موصلات الحساب، قُرئت في جلسة البناء","The account’s connector listing, read in the build session"],"limit":["«موصول» تعني مربوطًا وقابلًا للاستدعاء في ذلك اليوم، لا مستخدمًا في مشروع إنتاجي. العدد: ٢٢ خدمة في قائمة موصلات الحساب، منها ElevenLabs بموصلين، ومعها GitHub عبر خادم ملحق بجلسة البناء. أربع خدمات أخرى مدرجة وغير موصولة.","Connected means linked and callable on that day, not used in a production project. The count: 22 services in the account’s connector listing, ElevenLabs among them through two connectors, plus GitHub through a server attached to the build session. Four more services were listed but not connected."]},{"id":"callable_operations","value":1000,"qualifier":"more_than","state":"observed","unit":["عملية قابلة للاستدعاء على الأقل","callable operations at least"],"display":["أكثر من ١٬٠٠٠","More than 1,000"],"label":["عمليات تعرضها الخدمات الموصولة مجتمعة","Operations the connected services expose together"],"start":"2026-11-25","end":"2026-11-25","source":["قائمة الموصلات في جلسة البناء","Connector list in the build session"],"limit":["حد أدنى وليس عدًّا دقيقًا. إعادة عد تقريبية لقائمة الأدوات في جلسة البناء تتوافق معه حتى مع حساب الخدمة ذات الموصلين مرة واحدة. يحصي العمليات لا الأدوات المستخدمة في الإنتاج.","A floor, not an exact count. A rough recount of the tool list in the build session is consistent with it, even when the service with two connectors is counted once. It counts operations, not tools used in production."]}],"series":[{"id":"monthly_commits","state":"verified","label":["الالتزامات الشهرية، من مايو إلى نوفمبر ٢٠٢٦","Monthly commits, May to November 2026"],"unit":["التزامًا","commits"],"points":[{"month":"2026-05","label":["مايو","May"],"value":342},{"month":"2026-06","label":["يونيو","Jun"],"value":1670},{"month":"2026-07","label":["يوليو","Jul"],"value":3534},{"month":"2026-08","label":["أغسطس","Aug"],"value":443},{"month":"2026-09","label":["سبتمبر","Sep"],"value":77},{"month":"2026-10","label":["أكتوبر","Oct"],"value":384},{"month":"2026-11","label":["نوفمبر","Nov"],"value":1486,"partial_to":"2026-11-25"}],"start":"2026-05","end":"2026-11-25","source":["سجل الإيداعات في مستودع سديد · عُدّ في ٢٥ نوفمبر ٢٠٢٦","git history of the SADEED repository · counted on 25 November 2026"],"limit":["نوفمبر حتى اليوم الخامس والعشرين فقط. مجموع الأشهر ٧٬٩٣٦، ويضاف إليه التزام شكلي واحد مؤرخ في 2025-01-01 ليبلغ المجموع ٧٬٩٣٧. الوتيرة متفاوتة بين الأشهر، ونعرضها كما هي.","November runs to the 25th only. The months sum to 7,936; one placeholder commit dated 2025-01-01 brings the total to 7,937. The pace varies from month to month, and it is shown as it is."]}],"estimates":[{"id":"prototype_planning_target","kind":"planning_target","state":"proposed","low":2,"high":6,"value":"2–6","unit":["أسابيع","weeks"],"display":["من أسبوعين إلى ستة أسابيع","2–6 weeks"],"label":["هدف تخطيطي لنموذج أولي محدد النطاق","Planning target for a scoped prototype"],"tag":["تقدير","Estimate"],"source":["توجيه المالك الرابع، القسم ٠٥ · ٢٥ نوفمبر ٢٠٢٦","Owner’s directive v4, section 05 · 25 November 2026"],"limit":["هدف نخطط به، وليس ضمانًا ولا متوسطًا مثبتًا لكل المشاريع. لم يُقَس مشروع واحد بالطريقتين.","A target we plan with, not a guarantee and not an average proven for every project. No single project has been measured both ways."]},{"id":"traditional_scenario","kind":"illustrative_scenario","state":"not_measured","low":12,"high":null,"value":12,"qualifier":"or_more","unit":["أسبوعًا","weeks"],"display":["١٢ أسبوعًا أو أكثر","12 weeks or more"],"label":["سيناريو توضيحي لمسار تقليدي متتابع","Illustrative scenario for a traditional sequential path"],"tag":["سيناريو توضيحي","Illustrative scenario"],"source":["توجيه المالك الرابع، القسم ٠٥ · ٢٥ نوفمبر ٢٠٢٦","Owner’s directive v4, section 05 · 25 November 2026"],"limit":["مثال للمقارنة، وليس قياسًا لشركة بعينها ولا متوسطًا للسوق.","An illustration for comparison, not a measurement of any company and not a market average."]}],"assumptions":[{"key":"same_scope","text":["النطاق نفسه: الميزات نفسها وحالات القبول نفسها في المسارين.","The same scope: the same features and the same acceptance cases on both paths."]},{"key":"same_quality","text":["الجودة نفسها: اختبارات الأمان والجودة لا تُلغى في أي مسار، والتوازي لا يختصرها.","The same quality: security and quality tests are removed on neither path, and parallel work does not shorten them."]},{"key":"same_resources","text":["الموارد نفسها: حجم الفريق وتكلفة الأسبوع للفرد متساويان في المسارين.","The same resources: team size and weekly cost per person are equal on both paths."]},{"key":"same_delivery_terms","text":["شروط التسليم نفسها: نقطة بداية ونقطة نهاية معرَّفتان، وتعريف واحد لكلمة «منجز».","The same delivery terms: a defined start and end point, and one definition of done."]},{"key":"demo_not_production","text":["العرض التجريبي ليس منتجًا إنتاجيًّا: النموذج الأولي يُقارَن بنموذج أولي، لا بنظام كامل في التشغيل.","A demo is not a production product: a prototype is compared with a prototype, not with a full system in operation."]},{"key":"elapsed_time","text":["الزمن المحسوب هو زمن الساعة المنقضي: الفترات المتوازية لا تُجمع.","Time means elapsed clock time: parallel intervals are never added together."]},{"key":"no_guarantee","text":["لا ضمان بتسليم أي نظام خلال أسابيع. المدة تتغير بحجم النطاق وسرعة الموافقات وجاهزية الأنظمة المراد ربطها.","No system is guaranteed within weeks. Duration changes with the size of the scope, the speed of approvals and the readiness of the systems to be connected."]}],"not_measured":[{"id":"like_for_like_comparison","state":"not_measured","text":["مقارنة سرعتنا بفريق شركة على الميزة نفسها: لم تُجرَ تجربة متكافئة في النطاق والفريق وبوابات الجودة.","Our speed against a company team on the same feature: no trial with matched scope, team and quality gates has been run."]},{"id":"feature_development_time","state":"not_measured","text":["زمن تطوير ميزة من الصفر، ونسبة تحسّن سرعتنا عبر الزمن: لا يوجد تكليفان متكافئان مؤرَّخان.","Time to develop a feature from scratch, and how much faster we have become: no two dated, comparable briefs exist."]}],"stages":[{"key":"discovery","kind":"serial","label":["الاستكشاف","Discovery"],"what":["نتفق على قرار واحد وصاحبه واختبار قبوله.","One decision, its owner and its acceptance test are agreed."]},{"key":"spec","kind":"serial","label":["المواصفة","Spec"],"what":["يتحول الطلب إلى تكليف قابل للاختبار: المستخدم، والبيانات، والصلاحيات، وحالة ناجحة وأخرى فاشلة.","The request becomes a testable brief: the user, the data, the permissions, one passing case and one failing case."]},{"key":"architecture","kind":"serial","label":["البنية","Architecture"],"what":["عقد البيانات، وقواعد الوصول، وتقسيم العمل إلى مسارات مستقلة.","The data contract, the access rules and the split into independent tracks."]},{"key":"parallel_build","kind":"parallel","label":["البناء المتوازي","Parallel Build"],"what":["مسارات مستقلة تُبنى في الوقت نفسه، ولا يعدّل مساران ملفًا واحدًا.","Independent tracks are built at the same time, and no two tracks edit one file."]},{"key":"integration","kind":"serial","label":["التكامل","Integration"],"what":["تلتقي المخرجات عند عقد بيانات واحد وتُربط بالواجهات الفعلية.","The outputs meet at one data contract and are connected to the real interfaces."]},{"key":"verification","kind":"gate","label":["التحقق","Verification"],"what":["تُفحص الاختبارات والصلاحيات وهوية النسخة. بوابات الأمان والجودة لا تُتخطى.","Tests, permissions and the build identity are checked. Security and quality gates are never skipped."]},{"key":"demo","kind":"serial","label":["العرض","Demo"],"what":["نموذج يعمل يُعرض على بيانات عيّنة آمنة. العرض ليس منتجًا إنتاجيًّا.","A working prototype is shown on safe sample data. A demo is not a production product."]},{"key":"iteration","kind":"loop","label":["التكرار","Iteration"],"what":["تعود الملاحظات إلى المواصفة، وتتكرر الدورة على تغيير أضيق.","Feedback returns to the spec, and the cycle repeats on a narrower change."]}],"drivers":[{"key":"spec_driven","state":"configured","label":["التطوير المبني على المواصفة","Spec-driven development"],"what":["تكليف مكتوب بحدود وعقد مخرجات قبل أي كود، فتقل إعادة العمل.","A written brief with limits and an output contract before any code, so there is less rework."],"evidence":["تكليف وكيل مكتوب لمستودع سديد بحدود صارمة وسبع مراحل وعقد مخرجات. تنفيذ مراحله غير مقاس في هذا العرض.","A written agent brief for the SADEED repository with hard limits, seven phases and an output contract. Execution of its phases is not measured in this showcase."]},{"key":"context_engineering","state":"observed","label":["هندسة السياق","Context engineering"],"what":["كل مسار يستلم الملفات والعقد التي يحتاجها فقط، فيقل ما يُقرأ بلا حاجة.","Each track receives only the files and the contract it needs, so less is read without need."],"evidence":["في هذه النسخة لكل مسار قائمة مصادر محددة وملفات يملكها، كما في قواعد العمل وعقد الصفحة.","In this edition each track has a named list of sources and the files it owns, as written in the working rules and the site contract."]},{"key":"coding_agents","state":"observed","label":["وكلاء برمجة بالتوازي","Coding agents in parallel"],"what":["العمل المستقل يُوزَّع على مسارات تعمل معًا، ونراجع كل تغيير قبل اعتماده.","Independent work is split across tracks that run together, and we review every change before it is accepted."],"evidence":["سجل التنفيذ المؤرخ ٢٥ نوفمبر ٢٠٢٦ يدوّن مسارات منفصلة لهذه النسخة. أثرها على المدة غير مقاس.","The execution log of 25 November 2026 records separate tracks for this edition. Their effect on duration is not measured."]},{"key":"reuse","state":"observed","label":["مكوّنات وخدمات يُعاد استخدامها","Reusable components and services"],"what":["قاعدة البيانات والنشر والتصميم والبريد خدمات موصولة تُستدعى، ولا تُبنى من الصفر.","Database, deployment, design and mail are connected services to call, not things to build from scratch."],"evidence":["٢٣ خدمة موصولة في ٢٥ نوفمبر ٢٠٢٦، و٣٥٣ ملف مهارة مكتوبة. «موصول» و«مكتوب» لا تعنيان مستخدمًا في الإنتاج.","23 services connected on 25 November 2026, and 353 written skill files. Connected and written do not mean used in production."]},{"key":"ci_cd","state":"observed","label":["فحوص آلية ونشر متصل","CI/CD"],"what":["فحوص آلية قبل الدمج، ثم تحقق من النسخة على النطاق بعد النشر.","Automated checks before a merge, then verification of the build on the domain after release."],"evidence":["أربع مهام فحص نجحت على رأس الفرع الرئيسي، ومهمة النشر المرتبطة فشلت. وفي تحديث #455 مضت ١٧ دقيقة و٢٢٫٧٩١ ثانية من الدمج إلى التحقق.","Four CI jobs passed on the head of the main branch, and the linked deploy job failed. For update #455, 17 minutes 22.791 seconds passed from merge to verification."]}],"calculator":{"label":["حاسبة مقارنة المدة والتكلفة","Duration and cost comparison calculator"],"tag":["تقدير","Estimate"],"disclaimer":["كل ناتج هنا تقدير يتغير بمدخلاتك، وليس قياسًا ولا عرض سعر ولا ضمانًا. المدخلات الافتراضية عيّنات للتجربة.","Every output here is an estimate that moves with your inputs. It is not a measurement, a quote or a guarantee. The default inputs are samples to try."],"currency":{"code":"SAR","label":["ر.س","SAR"],"note":["القيمة الافتراضية عيّنة للحساب، وليست سعرًا ولا أجرًا معلنًا.","The default value is a sample for the arithmetic, not a price or a stated rate."]},"inputs":[{"key":"traditional_weeks","symbol":"T","default":12,"min":4,"max":52,"step":1,"unit":["أسبوعًا","weeks"],"label":["مدة المسار التقليدي","Traditional path duration"],"help":["السيناريو التوضيحي: ١٢ أسبوعًا أو أكثر للنطاق نفسه.","The illustrative scenario: 12 weeks or more for the same scope."],"symbol_ar":"ت"},{"key":"our_weeks_low","symbol":"L","default":2,"min":1,"max":12,"step":1,"unit":["أسابيع","weeks"],"label":["الحد الأدنى لهدفنا التخطيطي","Lower bound of our planning target"],"help":["هدف تخطيطي لنموذج أولي محدد النطاق.","A planning target for a scoped prototype."],"symbol_ar":"د"},{"key":"our_weeks_high","symbol":"H","default":6,"min":1,"max":26,"step":1,"unit":["أسابيع","weeks"],"label":["الحد الأعلى لهدفنا التخطيطي","Upper bound of our planning target"],"help":["يجب ألّا يقل عن الحد الأدنى.","It must not be lower than the lower bound."],"symbol_ar":"ع"},{"key":"team_size","symbol":"N","default":3,"min":1,"max":20,"step":1,"unit":["أفراد","people"],"label":["حجم الفريق","Team size"],"help":["العدد نفسه في المسارين، حتى تكون المقارنة عادلة.","The same number on both paths, so the comparison is fair."],"symbol_ar":"ف"},{"key":"weekly_cost_per_person","symbol":"C","default":10000,"min":0,"max":100000,"step":500,"unit":["ر.س في الأسبوع للفرد","SAR per person per week"],"label":["تكلفة الأسبوع للفرد","Weekly cost per person"],"help":["ضع رقمك أنت. تكلفة الأدوات والنماذج غير مشمولة، وتضاف هنا إن كانت مؤثرة.","Enter your own figure. Tool and model usage costs are not included; add them here if they matter."],"symbol_ar":"ك"},{"key":"parallel_tracks","symbol":"P","default":3,"min":1,"max":8,"step":1,"unit":["مسارات","tracks"],"label":["المسارات المتوازية","Parallel tracks"],"help":["عدد المسارات المستقلة التي تُبنى معًا تحت مراجعة الفريق نفسه.","The number of independent tracks built at once under the same team’s review."],"symbol_ar":"م"},{"key":"rework_share","symbol":"R","default":0.25,"min":0,"max":0.6,"step":0.05,"unit":["حصة من المدة","share of duration"],"label":["حصة إعادة العمل والانتظار","Rework and waiting share"],"help":["الجزء من المدة التقليدية الذي يذهب في إعادة العمل وانتظار التوضيح. النموذج يفترض تجنبه كله، وهذا حده المتفائل؛ خفّض القيمة لتقدير أكثر تحفظًا.","The part of the traditional duration that goes to rework and waiting for clarification. The model assumes all of it is avoided, which is the optimistic bound; lower the value for a more conservative estimate."],"symbol_ar":"ر"}],"constants":[{"key":"serial_share","symbol":"S","value":0.4,"label":["حصة العمل غير القابل للتوازي","Share of work that cannot run in parallel"],"help":["الاستكشاف والمواصفة والبنية والتكامل والتحقق تبقى متتابعة. قيمة مفترضة معلنة، وليست قياسًا.","Discovery, spec, architecture, integration and verification stay sequential. A declared assumption, not a measurement."],"symbol_ar":"س"}],"formula":{"expr":"W = T × (1 − R) × (S + (1 − S) ÷ P)","expr_cost":"cost = W × N × C","expr_note":["الرموز بالعربية: ت المدة التقليدية، ر حصة إعادة العمل، س الحصة المتتابعة، م المسارات المتوازية، ف حجم الفريق، ك تكلفة الأسبوع للفرد.","Both expressions are shown left to right in both languages."],"text":["المدة المقدَّرة تساوي المدة التقليدية بعد طرح حصة إعادة العمل، مضروبة في مجموع الحصة المتتابعة وحصة العمل المتوازي مقسومة على عدد المسارات. والتكلفة تساوي المدة مضروبة في حجم الفريق ثم في تكلفة الأسبوع للفرد. الفريق والتكلفة الأسبوعية متساويان في المسارين.","Modelled weeks equal the traditional duration minus the rework share, multiplied by the sequential share plus the parallel share divided by the number of tracks. Cost equals weeks times team size times weekly cost per person. Team size and weekly cost are equal on both paths."],"reading":["التوازي يقصّر الجزء القابل للتوازي فقط. بوابات التحقق تبقى في الجزء المتتابع ولا تُختصر.","Parallel work shortens only the part that can run in parallel. The verification gates stay in the sequential part and are not shortened."],"expr_ar":"المدة المقدّرة = ت × (١ − ر) × (س + (١ − س) ÷ م)","expr_cost_ar":"التكلفة = المدة المقدّرة × ف × ك"},"outputs":[{"key":"traditional_cost","expr":"T * N * C","unit":["ر.س","SAR"],"label":["تكلفة المسار التقليدي","Cost of the traditional path"]},{"key":"modelled_weeks","expr":"T * (1 - R) * (S + (1 - S) / P)","unit":["أسابيع","weeks"],"label":["المدة المقدَّرة بعد التوازي","Modelled duration after parallel work"]},{"key":"modelled_cost","expr":"modelled_weeks * N * C","unit":["ر.س","SAR"],"label":["التكلفة المقدَّرة","Modelled cost"]},{"key":"inside_planning_target","expr":"L \u003c= modelled_weeks && modelled_weeks \u003c= H","unit":["نعم أو لا","yes or no"],"label":["هل تقع المدة المقدَّرة داخل الهدف التخطيطي؟","Does the modelled duration fall inside the planning target?"]},{"key":"planning_cost_low","expr":"L * N * C","unit":["ر.س","SAR"],"label":["التكلفة عند الحد الأدنى للهدف","Cost at the lower bound of the target"]},{"key":"planning_cost_high","expr":"H * N * C","unit":["ر.س","SAR"],"label":["التكلفة عند الحد الأعلى للهدف","Cost at the upper bound of the target"]},{"key":"weeks_earlier","expr":"T - modelled_weeks","unit":["أسابيع","weeks"],"label":["الفرق المقدَّر في المدة","Estimated difference in duration"]},{"key":"cost_difference","expr":"traditional_cost - modelled_cost","unit":["ر.س","SAR"],"label":["الفرق المقدَّر في التكلفة","Estimated difference in cost"]}],"messages":{"inside":["المدة المقدَّرة داخل الهدف التخطيطي.","The modelled duration is inside the planning target."],"above":["المدة المقدَّرة أطول من الهدف: ضيّق النطاق أو أضف مسارًا مستقلًّا.","The modelled duration is longer than the target: narrow the scope or add an independent track."],"below":["المدة المقدَّرة أقصر من الحد الأدنى للهدف: راجع المدخلات، فالتحقق لا يُختصر.","The modelled duration is shorter than the target’s lower bound: review the inputs, because verification is not shortened."]},"example":{"tag":["تقدير","Estimate"],"inputs":{"traditional_weeks":12,"our_weeks_low":2,"our_weeks_high":6,"team_size":3,"weekly_cost_per_person":10000,"parallel_tracks":3,"rework_share":0.25},"constants":{"serial_share":0.4},"outputs":{"traditional_cost":360000,"modelled_weeks":5.4,"modelled_cost":162000.0,"inside_planning_target":true,"planning_cost_low":60000,"planning_cost_high":180000,"weeks_earlier":6.6,"cost_difference":198000.0},"note":["نتيجة المدخلات الافتراضية، للتحقق من تنفيذ المعادلة. كلها تقديرات.","The result of the default inputs, to check an implementation of the formula. All of them are estimates."]}}};
